// Generated by cline-hook install opencode.
import { spawn } from "node:child_process";

const BINARY: string = "__CLINE_HOOK_BINARY__";
const BLOCK_EXIT_CODE = 2;
const PATCH_FILE = /^\*\*\* (Add|Update|Delete) File: (.+)$/;
const PATCH_MOVE = /^\*\*\* Move to: (.+)$/;

interface HookOutcome {
  blocked: boolean;
  message: string;
}

interface InputUpdate {
  updated_input: Record<string, unknown>;
  message?: string | null;
}

// The slice of opencode 2.x's plugin context (`@opencode/plugin`) this plugin uses.
interface SessionInfo {
  parentID?: string;
  location?: { directory?: string };
  time?: { idle?: unknown };
}

interface ToolResult {
  output?: unknown;
  content?: string | readonly unknown[];
  metadata?: unknown;
}

interface ToolEvent {
  tool: string;
  sessionID: string;
  agent: string;
  id: string;
  input: unknown;
}

interface ToolAfterEvent extends ToolEvent {
  status: "completed" | "error";
  result?: ToolResult;
  error?: { message: string };
}

interface PromptEvent {
  sessionID: string;
  prompt: { text: string };
}

interface CompactionEvent {
  sessionID: string;
  system: { type: "text"; text: string }[];
}

interface IdleEvent {
  sessionID: string;
  background: readonly { sessionID: string }[];
}

interface Context {
  location: { directory: string };
  session: {
    get(input: { sessionID: string }): Promise<SessionInfo>;
    synthetic(input: { sessionID: string; text: string; resume?: boolean }): Promise<unknown>;
    hook(name: "prompt", callback: (event: PromptEvent) => Promise<void>): Promise<unknown>;
    hook(name: "compaction", callback: (event: CompactionEvent) => Promise<void>): Promise<unknown>;
    hook(name: "experimental.idle", callback: (event: IdleEvent) => Promise<void>): Promise<unknown>;
  };
  tool: {
    hook(name: "execute.before", callback: (event: ToolEvent) => Promise<void>): Promise<unknown>;
    hook(name: "execute.after", callback: (event: ToolAfterEvent) => Promise<void>): Promise<unknown>;
  };
  mcp: { list(): Promise<{ data?: readonly { name: string }[] }> };
}

function runHook(payload: Record<string, unknown>, cwd: string): Promise<HookOutcome> {
  return new Promise((resolve) => {
    const child = spawn(BINARY, [], { cwd, env: { ...process.env, CLINE_HOOKS_FRONTEND: "opencode" } });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (chunk) => (stdout += chunk));
    child.stderr.on("data", (chunk) => (stderr += chunk));
    child.on("error", () => resolve({ blocked: false, message: "" }));
    child.on("close", (code) => {
      if (code === BLOCK_EXIT_CODE) resolve({ blocked: true, message: stderr.trim() });
      else resolve({ blocked: false, message: code === 0 ? stdout.trim() : "" });
    });
    child.stdin.on("error", () => undefined);
    child.stdin.end(JSON.stringify(payload));
  });
}

function parseInputUpdate(output: string): InputUpdate | undefined {
  if (!output.startsWith("{")) return undefined;
  try {
    const parsed = JSON.parse(output);
    if (parsed && typeof parsed.updated_input === "object" && parsed.updated_input !== null) return parsed;
  } catch {
    return undefined;
  }
  return undefined;
}

function sanitize(name: string): string {
  return name.replace(/[^a-zA-Z0-9_-]/g, "_");
}

function record(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" ? (value as Record<string, unknown>) : {};
}

// Split a patch into one patch per file, so every file it touches is checked. A moved file is also
// checked at its destination.
function splitPatch(text: string): string[] {
  const lines = text.split("\n");
  const starts = lines.flatMap((line, index) => (PATCH_FILE.test(line) ? [index] : []));
  if (starts.length === 0) return [text];
  const sections: string[] = [];
  starts.forEach((start, n) => {
    const end = n + 1 < starts.length ? starts[n + 1] : lines.length;
    const body = lines.slice(start, end).filter((line) => !line.startsWith("*** End Patch"));
    sections.push(["*** Begin Patch", ...body, "*** End Patch"].join("\n"));
    const move = body.map((line) => PATCH_MOVE.exec(line)).find(Boolean);
    if (move) {
      const moved = [`*** Update File: ${move[1]}`, ...body.slice(1).filter((line) => !PATCH_MOVE.test(line))];
      sections.push(["*** Begin Patch", ...moved, "*** End Patch"].join("\n"));
    }
  });
  return sections.length === 1 ? [text] : sections;
}

function inputsOf(event: ToolEvent): unknown[] {
  const input = record(event.input);
  if (event.tool !== "patch" || typeof input.patchText !== "string") return [event.input];
  return splitPatch(input.patchText).map((patchText) => ({ ...input, patchText }));
}

function resultText(event: ToolAfterEvent): string {
  if (event.status === "error") return event.error?.message ?? "";
  const content = event.result?.content;
  if (typeof content === "string") return content;
  const texts = (content ?? []).flatMap((item) => {
    const part = record(item);
    return part.type === "text" && typeof part.text === "string" ? [part.text] : [];
  });
  if (texts.length) return texts.join("\n");
  const output = event.result?.output;
  return typeof output === "string" ? output : JSON.stringify(output ?? "");
}

function contentOf(result: ToolResult): unknown[] {
  if (typeof result.content === "string") return [{ type: "text", text: result.content }];
  if (result.content?.length) return [...result.content];
  const output = result.output;
  return [{ type: "text", text: typeof output === "string" ? output : JSON.stringify(output ?? "") }];
}

async function setup(ctx: Context) {
  const sessions = new Map<string, Promise<SessionInfo | undefined>>();
  const agents = new Map<string, string>();
  const spawning = new Map<string, string[]>();
  const started = new Set<string>();
  const stopActive = new Set<string>();
  const notes = new Map<string, string[]>();
  let mcpServers: Promise<string[]> | undefined;

  const sessionOf = (sessionID: string) => {
    let info = sessions.get(sessionID);
    if (!info) {
      info = ctx.session.get({ sessionID }).then(
        (result) => result,
        () => undefined,
      );
      sessions.set(sessionID, info);
    }
    return info;
  };

  const toolName = async (tool: string) => {
    mcpServers ??= ctx.mcp.list().then(
      (result) =>
        (result.data ?? []).map((server) => server.name).sort((a, b) => sanitize(b).length - sanitize(a).length),
      () => [],
    );
    for (const server of await mcpServers) {
      const prefix = `${sanitize(server)}_`;
      if (tool.startsWith(prefix)) return `mcp__${server}__${tool.slice(prefix.length)}`;
    }
    return tool;
  };

  const hook = async (sessionID: string, payload: Record<string, unknown>) => {
    const info = await sessionOf(sessionID);
    const cwd = info?.location?.directory ?? ctx.location.directory;
    const child = Boolean(info?.parentID);
    return runHook(
      {
        session_id: sessionID,
        cwd,
        agent_type: child ? (agents.get(sessionID) ?? "") : "",
        agent_id: child ? sessionID : undefined,
        ...payload,
      },
      cwd,
    );
  };

  const toolPayload = async (event: ToolEvent, input: unknown) => ({
    tool_name: await toolName(event.tool),
    tool_input: input,
  });

  await ctx.session.hook("prompt", async (event) => {
    try {
      const { sessionID } = event;
      stopActive.delete(sessionID);
      const messages: string[] = [];
      if (!started.has(sessionID)) {
        started.add(sessionID);
        const info = await sessionOf(sessionID);
        const agent = info?.parentID ? spawning.get(info.parentID)?.shift() : undefined;
        if (agent) agents.set(sessionID, agent);
        const { message } = await hook(sessionID, {
          hook_event_name: "session.start",
          source: info?.time?.idle ? "resume" : "startup",
        });
        if (message) messages.push(message);
      }
      const { message } = await hook(sessionID, { hook_event_name: "session.prompt", prompt: event.prompt.text });
      if (message) messages.push(message);
      for (const text of messages) await ctx.session.synthetic({ sessionID, text, resume: false });
    } catch {
      // A hook failure never stops the prompt.
    }
  });

  await ctx.tool.hook("execute.before", async (event) => {
    if (event.agent && !agents.has(event.sessionID)) agents.set(event.sessionID, event.agent);
    const inputs = inputsOf(event);
    const messages: string[] = [];
    for (const input of inputs) {
      const outcome = await hook(event.sessionID, {
        hook_event_name: "tool.execute.before",
        ...(await toolPayload(event, input)),
      });
      if (outcome.blocked) throw new Error(outcome.message);
      const update = parseInputUpdate(outcome.message);
      if (update && inputs.length === 1) event.input = { ...record(event.input), ...update.updated_input };
      const message = update ? update.message : outcome.message;
      if (message) messages.push(message);
    }
    const input = record(event.input);
    if (event.tool === "subagent" && !input.sessionID && typeof input.agent === "string") {
      spawning.set(event.sessionID, [...(spawning.get(event.sessionID) ?? []), input.agent]);
    }
    if (messages.length) notes.set(event.id, messages);
  });

  await ctx.tool.hook("execute.after", async (event) => {
    try {
      const pending = notes.get(event.id) ?? [];
      notes.delete(event.id);
      const response = { success: event.status === "completed", result: resultText(event) };
      for (const input of inputsOf(event)) {
        const { message } = await hook(event.sessionID, {
          hook_event_name: "tool.execute.after",
          ...(await toolPayload(event, input)),
          tool_response: response,
        });
        if (message) pending.push(message);
      }
      if (pending.length && event.status === "completed" && event.result) {
        const note = { type: "text", text: pending.join("\n\n") };
        event.result = { ...event.result, content: [...contentOf(event.result), note] };
      }
    } catch {
      // A hook failure never fails the tool call.
    }
  });

  await ctx.session.hook("compaction", async (event) => {
    try {
      const { message } = await hook(event.sessionID, { hook_event_name: "session.compaction" });
      if (message) event.system.push({ type: "text", text: message });
    } catch {
      // A hook failure never stops the compaction.
    }
  });

  await ctx.session.hook("experimental.idle", async (event) => {
    try {
      const { sessionID } = event;
      if ((await sessionOf(sessionID))?.parentID) return;
      // The session wakes again when its own background work finishes.
      if (event.background.some((work) => work.sessionID === sessionID)) return;
      const outcome = await hook(sessionID, {
        hook_event_name: "session.idle",
        stop_hook_active: stopActive.has(sessionID),
      });
      if (!outcome.blocked || !outcome.message) return;
      stopActive.add(sessionID);
      await ctx.session.synthetic({ sessionID, text: outcome.message });
    } catch {
      // A hook failure never stops the session going idle.
    }
  });
}

export default { id: "cline-hooks", setup };
